    mov.u32 %k, 0;
k_loop:
    setp.ge.u32 %p2, %k, %k_sz;
    @%p2 bra i_next;   // exit k loop

    // ---- Compute input index ----
    // bc_tmp = batch_idx * in_c + i
    mul.lo.u32 %bc_tmp, %batch_idx, %in_c;
    add.u32 %bc_tmp, %bc_tmp, %i;

