    mul.lo.u32 %w_tmp, %w_tmp, %k_sz;
    add.u32 %w_idx, %w_tmp, %k;

    mul.wide.u32 %w_off, %w_idx, 2;
    add.u64 %w_addr, %w_base, %w_off;

