    mul.lo.u32 %temp, %batch_idx, %out_c;
    add.u32 %temp, %temp, %out_c_idx;
    mul.lo.u32 %temp, %temp, %out_len;
    add.u32 %temp, %temp, %out_pos;
    mul.wide.u32 %out_off, %temp, 2;
    add.u64 %out_addr, %out_base, %out_off;

    // Convert accumulator to fp16 (round‑to‑nearest)
    cvt.rn.f16.f32 %out_f16, %sum;
    st.global.f16 [%out_addr], %out_f16;

