# --------------------------------------------------------------
class ModelNew:
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        import torch
        self.in_c = in_channels
        self.out_c = out_channels
        self.k_sz = kernel_size
        # weight tensor: (out_c, in_c, k_sz) in fp16
        self.weight = torch.randn(out_channels, in_channels, kernel_size,
                                  dtype=torch.float16, device='cuda')
        # load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: 'torch.Tensor') -> 'torch.Tensor':
        import torch
        batch, _, length = x.shape
        out_len = length - self.k_sz + 1
        y = torch.empty(batch, self.out_c, out_len,
                        dtype=torch.float16, device='cuda')
        # total output elements
        total = batch * self.out_c * out_len
        block = 256
        grid_x = (total + block - 1) // block
        # launch kernel
        args = [
            y.data_ptr(),
            x.data_ptr(),
            self.weight.data_ptr(),
            batch,
            self.in_c,
            self.out_c,
            length,
            self.k_sz
        ]
        ptx_launch(self.module, "conv1d_fp16",
                    (grid_x, 1, 1), (block, 1, 1), args)
        return y
